import numpy as np

def apply_rules(grid):
    N = grid.shape[0]
    new_grid = grid.copy()

    # Store changes to apply simultaneously
    updates = {} # Key: (r, c), Value: new state (0 or 1)

    # Iterate over all 2x2 squares
    for r in range(N - 1):
        for c in range(N - 1):
            # Check the 2x2 square centered at (r, c) with corners (r, c), (r+1, c), (r, c+1), (r+1, c+1)

            subgrid = np.array([
                grid[r, c], grid[r, c+1],
                grid[r+1, c], grid[r+1, c+1]
            ])

            infected_count = np.sum(subgrid)

            # Rule 1: 3 infected -> last sterile gets infected (Growth)
            if infected_count == 3:
                # Find the sterile cell (the one that needs to flip)
                sterile_cells = [(i, j) for i, j in [(r, c), (r, c+1), (r+1, c), (r+1, c+1)] if grid[i][j] == 0]

                # There must be exactly one sterile cell
                if len(sterile_cells) == 1:
                    ir, ic = sterile_cells[0]
                    # Mark for infection if it's not already set to 1
                    updates[(ir, ic)] = 1

            # Rule 2: 2 infected -> mutation (Infected <-> Sterile)
            elif infected_count == 2:
                # Flip the state of all 4 cells
                for i, j in [(r, c), (r, c+1), (r+1, c), (r+1, c+1)]:
                    current_state = grid[i, j]
                    new_state = 1 - current_state # Flip state
                    updates[(i, j)] = new_state

    # Apply all updates simultaneously
    for (r, c), state in updates.items():
        new_grid[r, c] = state

    return new_grid

def simulate(initial_grid, max_steps=1000):
    grid = initial_grid.copy()
    history = set()

    for step in range(max_steps):
        state_tuple = tuple(map(tuple, grid))

        # Check for cycle
        if state_tuple in history:
            # print(f"Cycle detected at step {step}")
            return False # Failed to spread fully (stuck in cycle)
        history.add(state_tuple)

        # Check for full infection
        if np.sum(grid) == grid.size:
            return True # Success!

        next_grid = apply_rules(grid)

        # Check if state stopped changing (stable configuration)
        if np.array_equal(grid, next_grid):
            return False # Failed to spread fully (stuck in stable state)

        grid = next_grid

    # If max_steps reached without success or cycle detection based on states
